-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 14 recettes, 0 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';
    if jsonb_typeof(ph) is distinct from 'object'
       or nullif(ph->>'url', '') is null or nullif(ph->>'page', '') is null
       or nullif(ph->>'license', '') is null then
      raise exception 'Photo vérifiée obligatoire pour %', r->>'slug';
    end if;
    -- Un nouveau slug ne doit pas recréer un plat déjà importé sous un autre nom.
    if exists (
      select 1 from public.recipes existing
      where existing.id <> rid and existing.country_code = r->>'country'
        and lower(regexp_replace(regexp_replace(coalesce(existing.original_title, existing.title), '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
          = lower(regexp_replace(regexp_replace(r->>'original', '\([^)]*\)', '', 'g'), '[^[:alnum:]]', '', 'g'))
    ) then
      raise exception 'Doublon de plat détecté pour %', r->>'slug';
    end if;

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, coalesce(r->>'reference', ph->>'page'),
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"oeufs-mimosa","country":"FR","original":"Œufs mimosa","title":"Œufs mimosa (œufs durs farcis à la mayonnaise)","en":"Œufs mimosa (French deviled eggs)","es":"Huevos mimosa (huevos rellenos con mayonesa)","desc":"Entrée de bistrot et de repas de famille : œufs durs coupés en deux, jaunes écrasés avec une mayonnaise à la moutarde, remis dans les blancs et parsemés de jaune émietté évoquant les fleurs de mimosa.","cat":"Entrée","diff":"easy","prep":20,"cook":10,"serv":4,"reference":"https://fr.wikipedia.org/wiki/%C5%92uf_mimosa","ing":[["Œufs",6,null,null],["Jaune d’œuf",1,null,"pour la mayonnaise"],["Moutarde de Dijon",1,"c. à thé",null],["Huile de tournesol",150,"ml",null],["Vinaigre de vin",1,"c. à thé",null],["Ciboulette ou persil",1,"c. à soupe","ciselé"],["Sel et poivre",1,"pincée",null]],"steps":["Cuire les œufs 10 minutes à l’eau bouillante, les refroidir dans l’eau glacée et les écaler.","Monter une mayonnaise ferme avec le jaune, la moutarde, l’huile, le vinaigre, le sel et le poivre.","Couper les œufs en deux dans la longueur, retirer les jaunes et en réserver deux.","Écraser les autres jaunes avec la mayonnaise et garnir les blancs à la cuillère ou à la poche.","Émietter les jaunes réservés au-dessus à travers une passoire, parsemer d’herbes et servir frais."],"photo":{"file":"File:Oeufs momisa 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/79/Oeufs_momisa_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Oeufs_momisa_2.jpg","author":"Jpbrigand2","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"poireaux-vinaigrette","country":"FR","original":"Poireaux vinaigrette","title":"Poireaux vinaigrette (blancs de poireaux à la moutarde)","en":"Leeks vinaigrette","es":"Puerros a la vinagreta","desc":"Entrée de bistrot : jeunes poireaux cuits à l’eau jusqu’à ce qu’ils soient fondants, servis tièdes nappés d’une vinaigrette à la moutarde, parfois avec œuf dur mimosa et échalote.","cat":"Entrée","diff":"easy","prep":15,"cook":20,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Poireaux_vinaigrette","ing":[["Poireaux fins",8,null,"le blanc et le vert tendre"],["Moutarde de Dijon",1,"c. à soupe",null],["Vinaigre de vin",2,"c. à soupe",null],["Huile",6,"c. à soupe",null],["Échalote",1,null,"ciselée"],["Œuf dur",1,null,"facultatif"],["Ciboulette",1,"c. à soupe",null],["Sel et poivre",1,"pincée",null]],"steps":["Fendre légèrement les poireaux, les laver soigneusement et les ficeler en botte.","Les cuire 15 à 20 minutes à l’eau bouillante salée jusqu’à ce qu’ils soient tendres.","Les égoutter puis les presser doucement pour retirer l’eau.","Fouetter la moutarde, le vinaigre, le sel et le poivre, puis l’huile et l’échalote.","Napper les poireaux tièdes de vinaigrette, parsemer d’œuf dur émietté et de ciboulette."],"photo":{"file":"File:Poireaux vinaigrette Dijon.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Poireaux_vinaigrette_Dijon.jpg","page":"https://commons.wikimedia.org/wiki/File:Poireaux_vinaigrette_Dijon.jpg","author":"Benreis","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"celeri-remoulade","country":"FR","original":"Céleri rémoulade","title":"Céleri rémoulade (céleri-rave à la mayonnaise moutardée)","en":"Céleri rémoulade (celeriac in mustard mayonnaise)","es":"Apio nabo rémoulade (con mayonesa de mostaza)","desc":"Crudité classique des brasseries et des traiteurs : céleri-rave râpé en fine julienne, assaisonné d’une mayonnaise relevée de moutarde et de citron.","cat":"Entrée","diff":"easy","prep":20,"cook":0,"serv":4,"reference":"https://fr.wikipedia.org/wiki/C%C3%A9leri_r%C3%A9moulade","ing":[["Céleri-rave",1,null,"environ 600 g"],["Citron",1,null,"jus"],["Jaune d’œuf",1,null,null],["Moutarde de Dijon",2,"c. à soupe",null],["Huile",150,"ml",null],["Crème fraîche",2,"c. à soupe","facultatif"],["Persil",1,"c. à soupe","haché"],["Sel et poivre",1,"pincée",null]],"steps":["Éplucher le céleri et le râper en fine julienne.","L’arroser aussitôt de jus de citron et d’une pincée de sel pour qu’il ne noircisse pas; laisser 10 minutes.","Monter une mayonnaise bien moutardée avec le jaune, la moutarde et l’huile; ajouter la crème.","Mélanger le céleri égoutté avec la sauce et rectifier l’assaisonnement.","Réfrigérer 1 heure et servir parsemé de persil."],"photo":{"file":"File:Celeri remoulade classique.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/51/Celeri_remoulade_classique.jpg","page":"https://commons.wikimedia.org/wiki/File:Celeri_remoulade_classique.jpg","author":"Jpbrigand2","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"steak-tartare","country":"FR","place":"fr-paris","original":"Steak tartare","title":"Steak tartare préparé (bœuf cru haché au couteau, câpres et jaune d’œuf)","en":"Steak tartare","es":"Steak tartar","desc":"Classique des brasseries parisiennes : bœuf très frais haché au couteau, assaisonné de moutarde, câpres, cornichons, échalote et sauce Worcestershire, lié au jaune d’œuf et servi avec des frites.","cat":"Plat principal","diff":"easy","prep":25,"cook":0,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Steak_tartare","ing":[["Filet ou rumsteck de bœuf très frais",300,"g",null],["Jaunes d’œufs",2,null,null],["Échalote",1,null,"ciselée"],["Câpres",1,"c. à soupe","hachées"],["Cornichons",4,null,"hachés"],["Moutarde de Dijon",1,"c. à soupe",null],["Sauce Worcestershire",1,"c. à thé",null],["Tabasco",3,"gouttes",null],["Huile d’olive",1,"c. à soupe",null],["Persil",1,"c. à soupe","haché"],["Sel et poivre",1,"pincée",null]],"steps":["Garder la viande au froid jusqu’au dernier moment, puis la hacher finement au couteau.","Mélanger la moutarde, un jaune, la Worcestershire, le Tabasco, l’huile, le sel et le poivre.","Ajouter l’échalote, les câpres, les cornichons et le persil, puis la viande, et mélanger sans écraser.","Dresser en galette à l’emporte-pièce sur des assiettes froides.","Poser un jaune d’œuf ou servir les condiments à part, avec des frites et une salade."],"photo":{"file":"File:Steak tartare Paris.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Steak_tartare_Paris.jpg","page":"https://commons.wikimedia.org/wiki/File:Steak_tartare_Paris.jpg","author":"Slywire","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"jambon-beurre","country":"FR","place":"fr-paris","original":"Jambon-beurre","title":"Jambon-beurre (baguette, beurre et jambon de Paris)","en":"Jambon-beurre (French ham and butter baguette)","es":"Jambon-beurre (baguette con mantequilla y jamón)","desc":"Le sandwich le plus vendu de France : une baguette fraîche fendue, généreusement beurrée au beurre doux ou demi-sel et garnie de jambon blanc, parfois de cornichons.","cat":"Cuisine de rue","diff":"easy","prep":5,"cook":0,"serv":2,"reference":"https://fr.wikipedia.org/wiki/Jambon-beurre","ing":[["Baguette de tradition",1,null,"fraîche"],["Beurre de bonne qualité",40,"g","mou"],["Jambon de Paris",4,"tranches",null],["Cornichons",4,null,"facultatif"]],"steps":["Couper la baguette en deux tronçons et les fendre dans la longueur sans les séparer.","Tartiner généreusement l’intérieur de beurre mou.","Plier les tranches de jambon et les répartir sur toute la longueur.","Ajouter des cornichons émincés si désiré.","Refermer en pressant légèrement et servir aussitôt."],"photo":{"file":"File:Jambon beurre classique.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Jambon_beurre_classique.jpg","page":"https://commons.wikimedia.org/wiki/File:Jambon_beurre_classique.jpg","author":"Al4az","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"tian-provencal","country":"FR","place":"fr-provence","original":"Tian provençal","title":"Tian provençal (légumes du soleil en rangs au four)","en":"Provençal tian (baked layered summer vegetables)","es":"Tian provenzal (verduras de verano al horno)","desc":"Gratin de Provence nommé d’après son plat en terre : rondelles d’aubergines, de courgettes et de tomates alternées sur un lit d’oignons, arrosées d’huile d’olive et de thym et cuites longuement.","cat":"Accompagnement","diff":"easy","prep":25,"cook":75,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Tian_(cuisine)","ing":[["Aubergines",2,null,"en rondelles"],["Courgettes",2,null,"en rondelles"],["Tomates",5,null,"en rondelles"],["Oignons",2,null,"émincés"],["Ail",3,"gousses",null],["Huile d’olive",6,"c. à soupe",null],["Thym et romarin",1,"c. à soupe",null],["Sel et poivre",1,"c. à thé",null]],"steps":["Faire fondre les oignons et l’ail 10 minutes dans 2 cuillerées d’huile d’olive et en tapisser un plat à gratin.","Ranger les rondelles de légumes debout en les alternant et en les serrant bien.","Saler, poivrer, parsemer de thym et de romarin et arroser du reste d’huile.","Couvrir d’aluminium et cuire 45 minutes à 180 °C.","Découvrir et poursuivre 30 minutes jusqu’à ce que les légumes soient confits et dorés."],"photo":{"file":"File:Tian provençal aux aubergines et aux tomates.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/3f/Tian_proven%C3%A7al_aux_aubergines_et_aux_tomates.jpg","page":"https://commons.wikimedia.org/wiki/File:Tian_proven%C3%A7al_aux_aubergines_et_aux_tomates.jpg","author":"Marianne Casamance","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"anchoiade","country":"FR","place":"fr-provence","original":"Anchoïade","title":"Anchoïade provençale (purée d’anchois à l’ail et à l’huile d’olive)","en":"Provençal anchoïade (anchovy and garlic spread)","es":"Anchoïade provenzal (crema de anchoas con ajo)","desc":"Préparation provençale d’anchois au sel dessalés, pilés avec l’ail et montés à l’huile d’olive avec un trait de vinaigre, servie sur des tartines grillées ou avec des crudités.","cat":"Entrée","diff":"easy","prep":15,"cook":5,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Ancho%C3%AFade","ing":[["Anchois au sel",150,"g","dessalés et levés en filets"],["Ail",3,"gousses",null],["Huile d’olive",120,"ml",null],["Vinaigre de vin",1,"c. à thé",null],["Câpres",1,"c. à soupe","facultatif"],["Poivre",0.5,"c. à thé",null],["Pain de campagne",6,"tranches","grillées"]],"steps":["Rincer les anchois, retirer l’arête centrale et les éponger.","Piler les anchois et l’ail au mortier jusqu’à obtenir une pâte.","Monter peu à peu avec l’huile d’olive en tournant, comme une mayonnaise.","Ajouter le vinaigre, les câpres hachées et le poivre.","Étaler sur les tranches de pain grillé et passer 2 minutes au four, ou servir en trempette avec des crudités."],"photo":{"file":"File:Anchoïade.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Ancho%C3%AFade.jpg","page":"https://commons.wikimedia.org/wiki/File:Ancho%C3%AFade.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"profiteroles-au-chocolat","country":"FR","place":"fr-paris","original":"Profiteroles au chocolat","title":"Profiteroles au chocolat chaud (choux à la glace vanille)","en":"Chocolate profiteroles","es":"Profiteroles con chocolate","desc":"Dessert de brasserie : petits choux garnis de glace à la vanille, nappés au moment de servir d’une sauce au chocolat noir bien chaude, parfois parsemés d’amandes grillées.","cat":"Dessert","diff":"medium","prep":40,"cook":30,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Profiterole","ing":[["Eau",125,"ml",null],["Beurre",50,"g",null],["Farine",75,"g",null],["Œufs",2,null,null],["Sel",1,"pincée",null],["Glace à la vanille",500,"ml",null],["Chocolat noir",150,"g",null],["Crème liquide",150,"ml",null],["Amandes effilées grillées",2,"c. à soupe","facultatif"]],"steps":["Porter l’eau, le beurre et le sel à ébullition, ajouter la farine d’un coup et dessécher la pâte 1 minute.","Incorporer les œufs un à un, pocher 18 petits choux et cuire 25 minutes à 180 °C sans ouvrir le four.","Faire fondre le chocolat dans la crème chaude jusqu’à obtenir une sauce lisse.","Couper les choux refroidis en deux et les garnir d’une boule de glace.","Dresser 3 choux par assiette et napper de sauce chocolat chaude; parsemer d’amandes."],"photo":{"file":"File:Paris 2e - Rue Vivienne - Restaurant Le Vaudeville - Profiteroles au chocolat.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/75/Paris_2e_-_Rue_Vivienne_-_Restaurant_Le_Vaudeville_-_Profiteroles_au_chocolat.jpg","page":"https://commons.wikimedia.org/wiki/File:Paris_2e_-_Rue_Vivienne_-_Restaurant_Le_Vaudeville_-_Profiteroles_au_chocolat.jpg","author":"Romainbehar","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en"}},{"slug":"mille-feuille","country":"FR","place":"fr-paris","original":"Mille-feuille","title":"Mille-feuille à la crème pâtissière et glaçage fondant","en":"Mille-feuille (French vanilla slice)","es":"Milhojas francés","desc":"Pâtisserie française de trois couches de pâte feuilletée caramélisée alternées avec deux couches de crème pâtissière à la vanille, glacée de fondant blanc marbré de chocolat.","cat":"Dessert","diff":"hard","prep":60,"cook":30,"serv":8,"reference":"https://fr.wikipedia.org/wiki/Mille-feuille","ing":[["Pâte feuilletée",500,"g",null],["Sucre glace",2,"c. à soupe","pour caraméliser"],["Lait",500,"ml",null],["Jaunes d’œufs",5,null,null],["Sucre",120,"g",null],["Fécule de maïs",50,"g",null],["Gousse de vanille",1,null,null],["Beurre",50,"g",null],["Fondant pâtissier",200,"g",null],["Chocolat noir",30,"g","fondu"]],"steps":["Étaler la pâte en un grand rectangle fin, la piquer et la cuire 20 minutes à 190 °C entre deux plaques, puis la saupoudrer de sucre glace et la caraméliser 3 minutes à 230 °C.","Préparer une crème pâtissière avec le lait vanillé, les jaunes, le sucre et la fécule; ajouter le beurre et refroidir.","Couper la pâte en trois bandes égales.","Monter le gâteau en alternant pâte et crème, en finissant par une bande de pâte face lisse vers le haut.","Glacer au fondant tiède, tracer des lignes de chocolat, les marbrer à la pointe du couteau et réfrigérer 2 heures avant de trancher."],"photo":{"file":"File:Mille-feuille 20100916.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Mille-feuille_20100916.jpg","page":"https://commons.wikimedia.org/wiki/File:Mille-feuille_20100916.jpg","author":"Georges Seguin (Okki)","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}},{"slug":"creme-caramel","country":"FR","original":"Crème caramel","title":"Crème renversée au caramel","en":"Crème caramel","es":"Flan de caramelo (crème caramel)","desc":"Dessert familial français : crème aux œufs et au lait vanillé cuite au bain-marie dans un moule chemisé de caramel, puis démoulée pour que le caramel la nappe.","cat":"Dessert","diff":"easy","prep":20,"cook":45,"serv":6,"reference":"https://fr.wikipedia.org/wiki/Cr%C3%A8me_renvers%C3%A9e","ing":[["Lait entier",750,"ml",null],["Œufs",5,null,null],["Sucre",120,"g","pour la crème"],["Gousse de vanille",1,null,"fendue"],["Sucre",120,"g","pour le caramel"],["Eau",3,"c. à soupe",null]],"steps":["Cuire le sucre et l’eau en caramel ambré et en napper le fond d’un moule ou de ramequins.","Porter le lait à ébullition avec la vanille, puis laisser infuser 10 minutes.","Fouetter les œufs et le sucre sans faire mousser, puis verser le lait chaud en filet.","Filtrer dans le moule et cuire 45 minutes au bain-marie à 150 °C, jusqu’à ce que la crème soit prise.","Refroidir puis réfrigérer au moins 4 heures; démouler en passant une lame sur le bord."],"photo":{"file":"File:Crème au caramel 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/7/7b/Cr%C3%A8me_au_caramel_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Cr%C3%A8me_au_caramel_2.jpg","author":"muriel amaury from France","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"macarons-parisiens","country":"FR","place":"fr-paris","original":"Macarons parisiens","title":"Macarons parisiens (coques d’amande et ganache)","en":"Parisian macarons","es":"Macarons parisinos","desc":"Petits gâteaux ronds popularisés à Paris au XXᵉ siècle : deux coques lisses et brillantes à la poudre d’amandes et à la meringue, au pied caractéristique, réunies par une ganache ou une crème parfumée.","cat":"Dessert","diff":"hard","prep":60,"cook":15,"serv":24,"reference":"https://fr.wikipedia.org/wiki/Macaron","ing":[["Poudre d’amandes",150,"g",null],["Sucre glace",150,"g",null],["Blancs d’œufs",110,"g","vieillis, en deux parts"],["Sucre",150,"g","pour la meringue italienne"],["Eau",40,"ml",null],["Colorant alimentaire",1,"pointe","facultatif"],["Chocolat noir",150,"g","pour la ganache"],["Crème liquide",150,"ml","pour la ganache"]],"steps":["Tamiser ensemble la poudre d’amandes et le sucre glace, puis y mélanger 55 g de blancs et le colorant.","Cuire le sucre et l’eau à 118 °C et le verser sur 55 g de blancs montés pour faire une meringue italienne.","Incorporer la meringue tiède à la pâte d’amandes en macaronnant jusqu’à ce que la pâte fasse un ruban souple.","Pocher des disques de 3 cm, taper la plaque, laisser croûter 30 minutes et cuire 13 minutes à 150 °C.","Garnir les coques refroidies de ganache (chocolat fondu dans la crème chaude) et réfrigérer 24 heures avant de déguster."],"photo":{"file":"File:Stacked macarons, Paris 2010.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/2e/Stacked_macarons%2C_Paris_2010.jpg","page":"https://commons.wikimedia.org/wiki/File:Stacked_macarons,_Paris_2010.jpg","author":"Betsy Weber","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"}},{"slug":"gateau-opera","country":"FR","place":"fr-paris","original":"Opéra","title":"Gâteau opéra (biscuit Joconde, café et chocolat)","en":"Opéra cake","es":"Pastel Ópera","desc":"Entremets parisien des années 1950 attribué à la maison Dalloyau : fines couches de biscuit Joconde aux amandes imbibé de café, crème au beurre au café et ganache, couvertes d’un glaçage chocolat miroir.","cat":"Dessert","diff":"hard","prep":90,"cook":15,"serv":10,"reference":"https://fr.wikipedia.org/wiki/Op%C3%A9ra_(g%C3%A2teau)","ing":[["Poudre d’amandes",100,"g","pour le biscuit"],["Sucre glace",100,"g",null],["Œufs",4,null,null],["Blancs d’œufs",3,null,null],["Farine",30,"g",null],["Café fort",200,"ml","sucré, pour imbiber"],["Beurre mou",200,"g","pour la crème au beurre"],["Café soluble",1,"c. à soupe",null],["Chocolat noir",200,"g","pour ganache et glaçage"],["Crème liquide",150,"ml",null]],"steps":["Battre les œufs avec la poudre d’amandes et le sucre glace, ajouter la farine puis les blancs montés; étaler sur deux plaques et cuire 8 minutes à 220 °C.","Préparer une crème au beurre au café et une ganache avec 120 g de chocolat et la crème chaude.","Couper le biscuit en trois rectangles égaux et imbiber chacun de café.","Monter en alternant biscuit, crème au café, biscuit, ganache, biscuit et une fine couche de crème; lisser et réfrigérer 2 heures.","Couler le reste du chocolat fondu en glaçage, laisser prendre, puis égaliser les bords au couteau chaud."],"photo":{"file":"File:Gâteau opéra 20171005 143324.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/98/G%C3%A2teau_op%C3%A9ra_20171005_143324.jpg","page":"https://commons.wikimedia.org/wiki/File:G%C3%A2teau_op%C3%A9ra_20171005_143324.jpg","author":"Wowo2008","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"galette-complete","country":"FR","place":"fr-bretagne","original":"Galette complète","title":"Galette complète bretonne (sarrasin, jambon, œuf, emmental)","en":"Breton galette complète (buckwheat crêpe with ham, egg and cheese)","es":"Galette bretona completa (crepe de trigo sarraceno con jamón, huevo y queso)","desc":"La galette la plus servie des crêperies bretonnes : crêpe de farine de blé noir cuite sur le billig, garnie de jambon, de fromage râpé et d’un œuf au plat, les bords repliés en carré.","cat":"Plat principal","diff":"easy","prep":15,"cook":10,"serv":4,"reference":"https://fr.wikipedia.org/wiki/Galette_de_sarrasin","ing":[["Farine de sarrasin",250,"g",null],["Gros sel",1,"c. à thé",null],["Eau froide",600,"ml",null],["Œuf",1,null,"pour la pâte"],["Beurre demi-sel",40,"g","pour la cuisson"],["Jambon blanc",4,"tranches",null],["Emmental râpé",120,"g",null],["Œufs",4,null,"pour la garniture"]],"steps":["Mélanger la farine et le sel, ajouter l’eau peu à peu et l’œuf, puis battre la pâte 5 minutes; la laisser reposer au moins 2 heures.","Chauffer une crêpière ou un billig, la graisser de beurre et étaler une louche de pâte en fine couche.","Quand la galette se décolle, casser un œuf au centre et étaler le blanc, puis ajouter fromage et jambon.","Laisser cuire jusqu’à ce que le blanc soit pris, en ajoutant une noisette de beurre sur les bords.","Replier les quatre bords en carré autour du jaune et servir aussitôt, avec une bolée de cidre."],"photo":{"file":"File:Galette de sarrasin complète bretonne.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/08/Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg","page":"https://commons.wikimedia.org/wiki/File:Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg","author":"Arnaud 25","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}},{"slug":"gaufres-lilloises","country":"FR","place":"fr-flandre","original":"Gaufres fourrées lilloises","title":"Gaufres fourrées lilloises (gaufrettes à la vergeoise)","en":"Lille filled waffles (with brown beet sugar cream)","es":"Gofres rellenos de Lille (con azúcar moreno de remolacha)","desc":"Spécialité de Lille rendue célèbre par la maison Méert : deux fines gaufrettes ovales cuites au fer, fourrées d’une crème de beurre à la vergeoise et parfois à la vanille de Madagascar.","cat":"Dessert","diff":"medium","prep":40,"cook":20,"serv":12,"reference":"https://fr.wikipedia.org/wiki/Gaufre_fourr%C3%A9e","ing":[["Farine",250,"g",null],["Levure boulangère fraîche",10,"g",null],["Lait tiède",80,"ml",null],["Œufs",2,null,null],["Beurre mou",100,"g","pour la pâte"],["Sucre",30,"g",null],["Sel",1,"pincée",null],["Vergeoise blonde ou brune",120,"g","pour la garniture"],["Beurre mou",100,"g","pour la garniture"],["Vanille",1,"c. à thé",null]],"steps":["Délayer la levure dans le lait, puis pétrir avec la farine, les œufs, le beurre, le sucre et le sel; laisser lever 1 heure.","Diviser la pâte en boules de 25 g et les cuire une à une 1 minute dans un gaufrier à gaufrettes fines et ovales.","Couper chaque gaufre encore chaude en deux dans l’épaisseur.","Battre le beurre mou avec la vergeoise et la vanille jusqu’à obtenir une crème.","Garnir une moitié de crème, refermer et laisser raffermir au frais."],"photo":{"file":"File:Jielbeaumadier gaufres lilloises 2008.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Jielbeaumadier_gaufres_lilloises_2008.jpg","page":"https://commons.wikimedia.org/wiki/File:Jielbeaumadier_gaufres_lilloises_2008.jpg","author":"Jiel Beaumadier","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}}]$batch$::jsonb);
